def entry(id,typ,en,fr,**data):
 e={'id':id,'type':typ,'name':{'en':en,'fr':fr},'source':source,'data':{'ruleset':'dnd5e-2014','rulesSourceId':'tce','automation':manual,**data}};items.append(e);return e
